const I18N={};
for(const r of I18N_ROWS)for(let i=1;i<LANGS.length;i++){const l=LANGS[i];(I18N[l]||(I18N[l]={}))[r[0]]=r[i];}

// tradução com valores: $t("{n} rotas",{n:5}); espaços nas pontas são preservados
function $t(s,v){let r=String(s??"");
  if(LANG!=="pt"){const d=I18N[LANG];if(d){const m=/^(\s*)([\s\S]*?)(\s*)$/.exec(r);if(d[m[2]]!=null)r=m[1]+d[m[2]]+m[3];}}
  if(v)r=r.replace(/\{(\w+)\}/g,(m,k)=>k in v?v[k]:m);return r;}

