// textos fixos da página: data-t (texto), data-th (HTML), data-tp (placeholder), data-ta (aria-label)
function i18nStatic(){
  document.documentElement.lang=LANG;
  const norm=x=>x.replace(/\s+/g," ").trim();
  document.querySelectorAll("[data-t]").forEach(el=>{if(el.dataset.i18n==null)el.dataset.i18n=norm(el.textContent);el.textContent=$t(el.dataset.i18n);});
  document.querySelectorAll("[data-th]").forEach(el=>{if(el.dataset.i18n==null)el.dataset.i18n=norm(el.innerHTML);el.innerHTML=$t(el.dataset.i18n);});
  document.querySelectorAll("[data-tp]").forEach(el=>{if(el.dataset.i18nP==null)el.dataset.i18nP=el.getAttribute("placeholder")||"";el.setAttribute("placeholder",$t(el.dataset.i18nP));});
  document.querySelectorAll("[data-ta]").forEach(el=>{if(el.dataset.i18nA==null)el.dataset.i18nA=el.getAttribute("aria-label")||"";el.setAttribute("aria-label",$t(el.dataset.i18nA));});
  document.querySelectorAll(".langs button[data-lang]").forEach(b=>b.setAttribute("aria-pressed",String(b.dataset.lang===LANG)));
}
i18nStatic();
